#!/usr/bin/env bash
#
# 把 OOOSplat fork 的 CI 恢复起来 —— 一个人工向导。
# Generated by the /wizard skill.
#
# 为什么需要它：dengchenlong/ooosplat 的 Actions 被 GitHub 侧冻结了
#   "Workflows are not currently being run on this fork due to the scale of
#    GitHub Actions usage. A repository maintainer can choose to re-enable these."
# 仓库设置里已经是全开（enabled=true, allowed_actions=all），dispatch 依旧 422，
# Actions 页上也没有可点的启用按钮 —— 这几步只能人来做。
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

REPO_ROOT="${REPO_ROOT:-/g/ooosplat-worktrees/objmesh}"
FORK="dengchenlong/ooosplat"
UPSTREAM="ooolabdev/ooosplat"
BRANCH="${BRANCH:-feature/objmesh-splat}"

run_wizard() {

TOTAL_STAGES=7

# 记录写进 .cache/（仓库 .gitignore 第 17 行），不污染工作树。
mkdir -p "$REPO_ROOT/.cache"
ENV_FILE="$REPO_ROOT/.cache/ci-setup.env"

banner "OOOSplat fork CI 恢复向导"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "现状核对：到底是什么挡住了 CI"
say "先分清三种可能，否则会去改没用的设置。"
note "  ① 仓库设置关了 Actions  ② 账号被限  ③ GitHub 冻结了这个 fork"
printf '\n'

say "跑一条真实命令看结果，而不是猜："
# 注意：这里不能写 `curl ... | grep -q`。grep -q 命中就退出会关掉管道，
# curl 收到 SIGPIPE，配合本脚本的 set -o pipefail 会让整条管道返回非 0，
# 于是「抓到了横幅」反而走进 else 分支（实测踩过）。先落盘再判断。
_actions_html=$(curl -sL --max-time 25 "https://github.com/$FORK/actions" 2>/dev/null || true)
if printf '%s' "$_actions_html" | grep -c "not currently being run" >/dev/null; then
  warn "fork 页面横幅：Workflows are not currently being run on this fork"
  note "  → GitHub 侧冻结（原因写的是 scale of GitHub Actions usage）"
else
  note "没抓到冻结横幅（可能已解除，或页面结构改了）——继续往下看"
fi

if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  printf '\n'
  say "仓库设置这一层："
  gh api "repos/$FORK/actions/permissions" 2>&1 | sed 's/^/    /'
  note "  enabled=true + allowed_actions=all 说明不是设置被关"
  printf '\n'
  say "再拿 dispatch 探一次（这是最硬的判据）："
  _probe=$(gh api -X POST "repos/$FORK/actions/workflows/sam2-sidecar.yml/dispatches" -f ref=main 2>&1 || true)
  case "$_probe" in
    *"Actions has been disabled"*)
      warn "dispatch 被拒：Actions has been disabled for this repository (HTTP 422)"
      note "  → 设置页改不动，只能走 GitHub Support 或借上游 CI" ;;
    "") note "dispatch 成功（没有错误输出）——Actions 可能已经恢复" ;;
    *"{}"*) note "dispatch 返回空对象 —— 已受理，Actions 可用了" ;;
    *)  note "dispatch 返回：$_probe" ;;
  esac
else
  warn "gh 不可用或未登录；只做了页面横幅检查"
  SKIPPED+=("gh 检查（先跑 gh auth login）")
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "本地等价门禁：先确认代码本身是绿的"
say "CI 跑不了，不代表质量门禁可以缺；这一条是替代品。"
note "  scripts/ci-local.sh 跑的就是 workflows 里那几道："
note "  telemetry / npm test / engine-scripts / colmap-lock / build / bundle / licenses"
note "  + cargo fmt --check / cargo test / cargo clippy -D warnings"
printf '\n'
step "在另一个终端也可以自己跑：bash scripts/ci-local.sh --fast"
printf '\n'
if confirm "现在就跑一遍本地门禁（约 2-5 分钟）？"; then
  if ( cd "$REPO_ROOT" && bash scripts/ci-local.sh --fast ); then
    write_env CI_LOCAL_RESULT "green"
    say "本地门禁全绿 —— 推上去的代码本身没问题，缺的只是 CI 平台"
  else
    write_env CI_LOCAL_RESULT "red"
    warn "本地门禁有红的：先修，再谈 CI 恢复。上面的 ✗ 行就是缺口。"
  fi
else
  SKIPPED+=("本地门禁（用 bash scripts/ci-local.sh --fast 手动补）")
fi
write_env CI_LOCAL_AT "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "兜底路线：把 PR 开到上游，借上游的 CI"
say "实测结论：fork 自己的 Actions 被冻，但**来自 fork 的 PR 会在上游仓库跑 CI**。"
note "  证据：上游 pull_request 事件跑过 147 次，最近的是"
note "  Zhong-fan/ooosplat 的 PR 在 2026-10-26 触发了三个平台的门禁。"
note "  （这只跑 checkout 上游 workflow、无 secret 的 job，正是本仓库的形态）"
printf '\n'
open_url "https://github.com/$UPSTREAM/compare/main...dengchenlong:$BRANCH?expand=1"
printf '\n'
step "页面出来后确认 base = main，head = dengchenlong:$BRANCH"
step "如果这个 PR 已经开过，直接回到那个 PR 页面就行，别重复开"
printf '\n'
if confirm "要我用 gh 直接把 PR 开出来吗？（会在上游建 PR，算对外动作）"; then
  _pr=$( cd "$REPO_ROOT" && gh pr create --repo "$UPSTREAM" --base main \
           --head "dengchenlong:$BRANCH" --fill 2>&1 || true )
  case "$_pr" in
    https://*) write_env CI_PR_URL "$_pr"; say "PR: $_pr" ;;
    *) warn "gh pr create 没给出 URL，输出：$_pr"
       SKIPPED+=("建上游 PR（把上面的输出看一眼，必要时手动开）") ;;
  esac
else
  SKIPPED+=("建上游 PR（手动开：上面那个 compare 链接）")
fi
printf '\n'
ask CI_PR_URL "如果已经有 PR，把它的 URL 贴进来（可留空）：" || true
if [[ -n "${CI_PR_URL:-}" ]]; then write_env CI_PR_URL "$CI_PR_URL"; else write_env CI_PR_URL "none"; fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "正式路线：让 GitHub 解除 fork 冻结"
say "页面横幅写的是「A repository maintainer can choose to re-enable these」，"
say "但实测 Actions 页上没有可点的按钮，API 也没有对应开关。"
note "  已试过且无效：PUT /actions/permissions {enabled:true}（返回 200，dispatch 仍 422）"
note "                  gh workflow enable（对单个 workflow 有效，对冻结无效）"
note "                  gh api rerun（会卡在 queued 不落地，且无法 cancel）"
printf '\n'
open_url "https://support.github.com/contact"
printf '\n'
step "Topic 选 'GitHub Actions'，Repository 填 $FORK"
step "把下面整段（含 ---）复制进正文，它把所有证据都摆好了："
printf '\n'
cat <<TICKET
---
Repository: $FORK (public fork of $UPSTREAM)
Problem: Actions is frozen on this fork and cannot be re-enabled from settings or API.

What the Actions tab shows:
  "Workflows are not currently being run on this fork due to the scale of
   GitHub Actions usage. A repository maintainer can choose to re-enable these."

State of the repository settings (read via REST):
  GET /repos/$FORK/actions/permissions
  {"enabled":true,"allowed_actions":"all","sha_pinning_required":false}

What still fails:
  POST /repos/$FORK/actions/workflows/sam2-sidecar.yml/dispatches
  {"message":"Actions has been disabled for this repository.","status":"422"}
  PUT /repos/$FORK/actions/permissions {"enabled":true} returns 200 but the
  dispatch call above keeps returning 422.
  Re-running an old run leaves it in "queued" forever; cancelling it returns
  "Cannot cancel a workflow re-run that has not yet queued." (HTTP 409)

Context: this is a personal fork used for a research project. The last runs that
did execute are from 2026-10-14; nothing has run since. My account's non-fork
repositories run Actions normally (runs on 2026-11-03), so this is fork-specific.

Request: please re-enable Actions for this fork, or tell me which switch turns
this state off.
---

TICKET
printf '\n'
say "提交后 GitHub 会回一个工单号/链接。"
ask CI_SUPPORT_TICKET "工单号或 URL（可留空）：" || true
if [[ -n "${CI_SUPPORT_TICKET:-}" ]]; then write_env CI_SUPPORT_TICKET "$CI_SUPPORT_TICKET"; else write_env CI_SUPPORT_TICKET "pending"; fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "把 PR 的检查结论读回来"
if [[ -n "${CI_PR_URL:-}" && "${CI_PR_URL:-}" != "none" ]] && command -v gh >/dev/null 2>&1; then
  say "等三个平台的门禁跑完（Windows 约 20 分钟，Ubuntu 约 14，macOS 约 18）。"
  printf '\n'
  if confirm "现在就阻塞等结果（--watch，可能十几分钟）？"; then
    _n=$(printf '%s' "$CI_PR_URL" | grep -o '[0-9]*$' || true)
    gh pr checks "${_n:-$CI_PR_URL}" --repo "$UPSTREAM" --watch 2>&1 | sed 's/^/    /' || true
    printf '\n'
    say "结论表（再取一次快照）："
    gh pr checks "${_n:-$CI_PR_URL}" --repo "$UPSTREAM" 2>&1 | sed 's/^/    /' || true
  else
    note "稍后自己看：gh pr checks <num> --repo $UPSTREAM --watch"
    SKIPPED+=("读取 PR 检查结论")
  fi
else
  warn "还没有 PR URL，这一阶段跳过"
  SKIPPED+=("读取 PR 检查结论（先有会话里的 PR）")
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "冻结解除之后：验证 dispatch 真的能跑"
say "工单批下来后回到这步，用同一条命令复测 —— 这才是「CI 恢复了」的证据。"
printf '\n'
if confirm "现在就复测一次 dispatch 吗？"; then
  if command -v gh >/dev/null 2>&1; then
    _p=$(gh api -X POST "repos/$FORK/actions/workflows/sam2-sidecar.yml/dispatches" -f ref=main 2>&1 || true)
    if [[ -z "$_p" ]]; then
      write_env CI_DISPATCH_OK "yes"
      say "dispatch 成功 —— Actions 已经可以跑了。"
      note "接着可以：gh workflow run \"Windows x64\" --repo $FORK --ref $BRANCH"
    else
      write_env CI_DISPATCH_OK "no"
      warn "仍然失败：$_p"
      note "  → 把工单回复贴给 GitHub Support 继续跟"
    fi
  else
    warn "gh 不可用"
  fi
else
  SKIPPED+=("复测 dispatch（生产上跑：gh api -X POST repos/$FORK/actions/workflows/sam2-sidecar.yml/dispatches -f ref=main）")
  write_env CI_DISPATCH_OK "unknown"
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "收尾：把结论写进项目备忘录"
say "这次排查的结论值得留档，否则下次还会重新试一遍那些没用的开关。"
printf '\n'
note "  备忘录：E:/Documents/Notes/业余/项目管理/ooosplat/备忘录.md"
note "  追加要点：fork 冻结的三种判据、三个无效开关、两条可用替代（本地门禁 / 上游 PR CI）"
printf '\n'
step "把下面这段贴进备忘录（日期自己改）："
printf '\n'
cat <<MEMO
## $(date -u +%Y-%m-%d)（CI 路线结论）

- 现象：fork 的 Actions 被 GitHub 冻结（横幅 "Workflows are not currently being
  run on this fork due to the scale of GitHub Actions usage"）。设置侧已全开
  （enabled=true / allowed_actions=all），dispatch 仍 422。
- 无效的开关（别再试）：PUT /actions/permissions {enabled:true}（200 但无效）、
  gh workflow enable（只管单个 workflow）、rerun（卡 queued 且 cancel 返回 409）。
- 可用替代 ①：bash scripts/ci-local.sh [--fast|--full|--only rust|frontend|engines]
  —— 与 workflows 同款门禁，本地一次跑完。$( [ "${CI_LOCAL_RESULT:-}" = green ] && echo "本次：全绿。" || echo "本次：未跑或未全绿。" )
- 可用替代 ②：把 PR 开到上游（来自 fork 的 PR 会在上游跑 CI，147 次先例）。
- 正式路线：GitHub Support 工单，要求解除 fork 冻结。$( [ -n "${CI_SUPPORT_TICKET:-}" ] && echo "工单：$CI_SUPPORT_TICKET" || echo "工单：待提。" )
MEMO
printf '\n'
pause

finish
note "记录文件：$ENV_FILE"
if [[ -f "$ENV_FILE" ]]; then sed 's/^/    /' "$ENV_FILE"; fi
printf '\n'
note "先修红色项再推送：bash $REPO_ROOT/scripts/ci-local.sh --fast"
}

run_wizard "$@"; exit
